#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> words(n);
    for (auto &w : words) cin >> w;
    string t;
    cin >> t;
    int m = words[0].size(), T = t.size();
    // freq[i][c]: how many words have letter c in column i.
    vector<array<long long, 26>> freq(m);
    for (auto &f : freq) f.fill(0);
    for (auto &w : words)
        for (int i = 0; i < (int)w.size(); i++) freq[i][w[i] - 'a']++;
    vector<long long> dp(T + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < m; i++)
        for (int j = min(i + 1, T); j >= 1; j--)  // reverse so a column is used at most once
            dp[j] = (dp[j] + dp[j - 1] * freq[i][t[j - 1] - 'a']) % MOD;
    printf("%lld\n", dp[T]);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        final long MOD = 1000000007L;
        int n = nextInt();
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = next();
        String t = next();
        int m = words[0].length(), T = t.length();
        // freq[i*26+c]: how many words have letter c in column i.
        long[] freq = new long[m * 26];
        for (String w : words)
            for (int i = 0; i < w.length(); i++) freq[i * 26 + w.charAt(i) - 'a']++;
        long[] dp = new long[T + 1];
        dp[0] = 1;
        for (int i = 0; i < m; i++)
            for (int j = Math.min(i + 1, T); j >= 1; j--) // reverse so a column is used at most once
                dp[j] = (dp[j] + dp[j - 1] * freq[i * 26 + t.charAt(j - 1) - 'a']) % MOD;
        System.out.println(dp[T]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const MOD = 1000000007
	n := int(nextInt())
	words := make([][]byte, n)
	for i := range words {
		words[i] = next()
	}
	t := next()
	m, T := len(words[0]), len(t)
	// freq[i*26+c]: how many words have letter c in column i.
	freq := make([]int64, m*26)
	for _, w := range words {
		for i, c := range w {
			freq[i*26+int(c-'a')]++
		}
	}
	dp := make([]int64, T+1)
	dp[0] = 1
	for i := 0; i < m; i++ {
		for j := min(i+1, T); j >= 1; j-- { // reverse so a column is used at most once
			dp[j] = (dp[j] + dp[j-1]*freq[i*26+int(t[j-1]-'a')]) % MOD
		}
	}
	fmt.Println(dp[T])
}
